try {
  const body = $input.first().json.body || $input.first().json;
  const toolCallList = body?.message?.toolCallList || [];
  if (toolCallList.length === 0) throw new Error('empty toolCallList');
  const toolCall = toolCallList[0];
  const toolCallId = toolCall.id || 'unknown';
  let args = {};
  try { args = typeof toolCall.function?.arguments === 'string' ? JSON.parse(toolCall.function.arguments) : (toolCall.function?.arguments || {}); } catch(e) { args = {}; }
  const phone = (args.phone || args.patientPhone || '').trim();
  const patientName = (args.patientName || '').trim();
  const newDate = (args.newDate || args.appointmentDate || '').trim();
  const newTime = (args.newTime || args.appointmentTime || '').trim();
  if ((!phone && !patientName) || !newDate || !newTime) {
    return [{ json: { toolCallId, error: true, result: 'Randevu taşımak için hasta bilgisi, yeni tarih ve yeni saat gereklidir.' } }];
  }
  return [{ json: { toolCallId, phone, patientName, newDate, newTime, error: false } }];
} catch(e) {
  return [{ json: { toolCallId: 'unknown', error: true, result: 'İsteğinizi işlerken bir hata oluştu. Lütfen tekrar deneyin.' } }];
}

